#include "consumer_consumer.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void consumer_consumer_initialize(void);
void consumer_consumer_notify(microkit_channel channel);
void consumer_consumer_timeTriggered(void);

volatile sb_queue_int32_t_1_t *sample_queue_1;
sb_queue_int32_t_1_Recv_t sample_recv_queue;
volatile sb_queue_int32_t_1_t *observed_sample_queue_1;
volatile sb_queue_bool_1_t *alert_flag_queue_1;
sb_queue_bool_1_Recv_t alert_flag_recv_queue;

#define PORT_FROM_MON 0

bool sample_is_empty(void) {
  return sb_queue_int32_t_1_is_empty(&sample_recv_queue);
}

bool get_sample_poll(sb_event_counter_t *numDropped, int32_t *data) {
  return sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &sample_recv_queue, numDropped, data);
}

bool get_sample(int32_t *data) {
  sb_event_counter_t numDropped;
  return get_sample_poll (&numDropped, data);
}

bool put_observed_sample(const int32_t *data) {
  sb_queue_int32_t_1_enqueue((sb_queue_int32_t_1_t *) observed_sample_queue_1, (int32_t *) data);

  return true;
}

bool alert_flag_is_empty(void) {
  return sb_queue_bool_1_is_empty(&alert_flag_recv_queue);
}

bool get_alert_flag_poll(sb_event_counter_t *numDropped, bool *data) {
  return sb_queue_bool_1_dequeue((sb_queue_bool_1_Recv_t *) &alert_flag_recv_queue, numDropped, data);
}

bool get_alert_flag(bool *data) {
  sb_event_counter_t numDropped;
  return get_alert_flag_poll (&numDropped, data);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_int32_t_1_Recv_init(&sample_recv_queue, (sb_queue_int32_t_1_t *) sample_queue_1);

  sb_queue_int32_t_1_init((sb_queue_int32_t_1_t *) observed_sample_queue_1);

  sb_queue_bool_1_Recv_init(&alert_flag_recv_queue, (sb_queue_bool_1_t *) alert_flag_queue_1);

  consumer_consumer_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      consumer_consumer_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      consumer_consumer_notify(channel);
  }
}
